-- Run ONCE in a NEW Supabase project. No service key in browser.
begin;
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, nickname text not null check(length(nickname) between 1 and 40), role text not null check(role in ('student','teacher','admin')), approved boolean not null default false, organization text default '', created_at timestamptz default now());
create table public.classrooms(id uuid primary key default gen_random_uuid(), teacher_id uuid not null references profiles, name text not null, code text unique not null default upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)), created_at timestamptz default now());
create table public.classroom_members(student_id uuid primary key references profiles on delete cascade, classroom_id uuid not null references classrooms on delete cascade, joined_at timestamptz default now());
create table public.sharing_preferences(student_id uuid primary key references profiles on delete cascade, basic_shared boolean not null default false, consent_confirmed boolean not null default false, updated_at timestamptz default now());
create table public.daily_questions(id text primary key, weekday int not null check(weekday between 0 and 6), category text not null, prompt text not null, options jsonb not null, active boolean default true);
create table public.mood_records(id uuid primary key default gen_random_uuid(), student_id uuid not null references profiles on delete cascade, record_date date not null default (now() at time zone 'Asia/Seoul')::date, kind text not null check(kind in ('basic','theme','diary')), category text not null, question_id text, question text not null, answer text not null check(length(answer) between 1 and 3000), shared boolean not null default false, reward int not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create unique index one_basic_per_day on mood_records(student_id,record_date) where kind='basic';
create unique index one_theme_per_day on mood_records(student_id,record_date,question_id) where kind='theme';
create table public.bean_inventory(id uuid primary key default gen_random_uuid(), student_id uuid not null references profiles on delete cascade, bean text not null check(bean in ('pea','kidney','black','mung','peanut')), growth int not null default 0, target int not null default 30 check(target>=4), completed_at timestamptz, created_at timestamptz default now());
create unique index one_active_bean on bean_inventory(student_id) where completed_at is null;
create table public.water_transactions(id uuid primary key default gen_random_uuid(),student_id uuid not null references profiles on delete cascade, amount int not null, reason text not null, reference text, created_at timestamptz default now(), unique(student_id,reference));
create table public.reward_inventory(id uuid primary key default gen_random_uuid(), student_id uuid not null references profiles on delete cascade, label text not null, test_only boolean not null default true, used_at timestamptz, created_at timestamptz default now());
create table public.counseling_requests(id uuid primary key default gen_random_uuid(), student_id uuid not null references profiles on delete cascade, classroom_id uuid not null references classrooms, message text not null check(length(message) between 1 and 3000), status text not null default '확인 전' check(status in ('확인 전','확인 완료','상담 예정','상담 진행 완료','추가 확인 필요','취소')), followup boolean default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.counseling_notes(id uuid primary key default gen_random_uuid(),request_id uuid not null references counseling_requests on delete cascade, teacher_id uuid not null references profiles, body text not null check(length(body) between 1 and 5000), created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,body text not null,read_at timestamptz,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key, actor uuid, action text not null, entity text, created_at timestamptz default now());
create table public.operation_settings(id boolean primary key default true check(id),growth_target int not null default 30 check(growth_target>=4),retention_days int not null default 365 check(retention_days>=30));
insert into operation_settings default values;
create table public.referrals(invitee uuid primary key references profiles on delete cascade,inviter uuid not null references profiles on delete cascade,created_at timestamptz default now(),check(invitee<>inviter));
create table public.deletion_requests(student_id uuid primary key references profiles on delete cascade,created_at timestamptz default now());
create table public.roulette_events(id uuid primary key default gen_random_uuid(),student_id uuid not null references profiles on delete cascade, result text not null,created_at timestamptz default now());
create function public.my_role() returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create function public.teaches(s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from classroom_members m join classrooms c on c.id=m.classroom_id join profiles p on p.id=c.teacher_id where m.student_id=s and c.teacher_id=auth.uid() and p.approved)$$;
create function public.owns_class(c uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from classrooms x join profiles p on p.id=x.teacher_id where x.id=c and x.teacher_id=auth.uid() and p.approved)$$;
create function public.handle_signup() returns trigger language plpgsql security definer set search_path=public as $$begin
 insert into profiles(id,nickname,role,organization) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'nickname',''),'새 친구'),40),case when new.raw_user_meta_data->>'role'='teacher' then 'teacher' else 'student' end,left(coalesce(new.raw_user_meta_data->>'organization',''),100));
 insert into sharing_preferences(student_id) values(new.id); return new; end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_signup();
-- Realtime UI invalidation uses these tables, never disables RLS.
do $$declare t text;begin foreach t in array array['profiles','classrooms','classroom_members','sharing_preferences','daily_questions','mood_records','bean_inventory','water_transactions','reward_inventory','counseling_requests','counseling_notes','notifications','audit_logs','operation_settings','referrals','deletion_requests','roulette_events'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy profiles_read on profiles for select to authenticated using(id=auth.uid() or teaches(id));
create policy class_read on classrooms for select to authenticated using(owns_class(id) or exists(select 1 from classroom_members m where m.student_id=auth.uid() and m.classroom_id=classrooms.id));
create policy members_read on classroom_members for select to authenticated using(student_id=auth.uid() or owns_class(classroom_id));
create policy prefs_read on sharing_preferences for select to authenticated using(student_id=auth.uid());
create policy questions_read on daily_questions for select to authenticated using(active);
create policy records_read on mood_records for select to authenticated using(student_id=auth.uid() or (shared and teaches(student_id) and (kind<>'basic' or exists(select 1 from sharing_preferences p where p.student_id=mood_records.student_id and p.basic_shared and p.consent_confirmed))));
-- Preference subquery must not be hidden by its own RLS in teacher context.
create function public.basic_is_shared(s uuid) returns boolean language sql stable security definer set search_path=public as $$select coalesce((select basic_shared and consent_confirmed from sharing_preferences where student_id=s),false)$$;
drop policy records_read on mood_records;
create policy records_read on mood_records for select to authenticated using(student_id=auth.uid() or (shared and teaches(student_id) and (kind<>'basic' or basic_is_shared(student_id))));
create policy bean_read on bean_inventory for select to authenticated using(student_id=auth.uid());
create policy water_read on water_transactions for select to authenticated using(student_id=auth.uid());
create policy reward_read on reward_inventory for select to authenticated using(student_id=auth.uid());
create policy request_read on counseling_requests for select to authenticated using(student_id=auth.uid() or (owns_class(classroom_id) and teaches(student_id)));
create policy notes_read on counseling_notes for select to authenticated using(teacher_id=auth.uid() and exists(select 1 from counseling_requests r where r.id=request_id and owns_class(r.classroom_id) and teaches(r.student_id)));
create policy notify_read on notifications for select to authenticated using(user_id=auth.uid());
create policy settings_read on operation_settings for select to authenticated using(true);
create policy roulette_read on roulette_events for select to authenticated using(student_id=auth.uid());
create policy delete_read on deletion_requests for select to authenticated using(student_id=auth.uid());
create policy referrals_read on referrals for select to authenticated using(inviter=auth.uid() or invitee=auth.uid());
create policy audit_read on audit_logs for select to authenticated using(my_role()='admin');
-- ALL writes go through validated security-definer RPCs. Table grants alone are NOT authorization.
revoke all on all tables in schema public from anon,authenticated;
grant select on all tables in schema public to authenticated;
create function public.require_student() returns uuid language plpgsql security definer set search_path=public as $$begin if auth.uid() is null or my_role()<>'student' then raise exception '학생 계정이 필요합니다';end if;perform 1 from profiles where id=auth.uid() for update;return auth.uid();end$$;
create function public.balance(s uuid) returns bigint language sql stable security definer set search_path=public as $$select coalesce(sum(amount),0) from water_transactions where student_id=s$$;
create function public.create_class(p_name text) returns uuid language plpgsql security definer set search_path=public as $$declare c uuid;begin if not exists(select 1 from profiles where id=auth.uid() and role='teacher' and approved) then raise exception '승인된 교사 계정이 필요합니다';end if;if length(trim(p_name)) not between 1 and 80 then raise exception '학급 이름을 확인하세요';end if;insert into classrooms(teacher_id,name) values(auth.uid(),trim(p_name)) returning id into c;return c;end$$;
create function public.join_class(p_code text) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();c uuid;begin select id into c from classrooms where code=upper(trim(p_code));if c is null then raise exception '학급 코드를 확인하세요';end if;if exists(select 1 from classroom_members where student_id=s) then raise exception '이미 연결된 학급이 있습니다. 변경은 담당자에게 요청하세요';end if;insert into classroom_members values(s,c,now());end$$;
create function public.set_sharing(p_basic boolean,p_consent boolean) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();begin if p_basic and not p_consent then raise exception '안내 및 동의 절차 확인이 필요합니다';end if;update sharing_preferences set basic_shared=p_basic,consent_confirmed=p_consent,updated_at=now() where student_id=s;insert into audit_logs(actor,action) values(s,'sharing_changed');end$$;
create function public.choose_bean(p_bean text) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();begin insert into bean_inventory(student_id,bean,target) select s,p_bean,growth_target from operation_settings;end$$;
create function public.save_record(p_kind text,p_question_id text,p_answer text,p_shared boolean default false) returns int language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();d date:=(now() at time zone 'Asia/Seoul')::date;q daily_questions;expected text;old mood_records;v int:=0;begin
 if p_kind='diary' then insert into mood_records(student_id,kind,category,question,answer,shared) values(s,'diary','일기','나만의 마음 일기',trim(p_answer),false);return 0;end if;
 select * into q from daily_questions where id=p_question_id and active;if q.id is null then raise exception '유효한 질문이 아닙니다';end if;
 if p_kind='basic' then
 select id into expected from daily_questions where weekday=extract(dow from d)::int and active and category<>'테마' order by id offset ((d-date '2026-01-01') % greatest(1,(select count(*)::int from daily_questions where weekday=extract(dow from d)::int and active and category<>'테마'))) limit 1;
 if q.id<>expected then raise exception '오늘의 질문을 다시 불러오세요';end if;
 elsif p_kind='theme' then if q.category<>'테마' then raise exception '테마 질문만 선택할 수 있습니다';end if;else raise exception '기록 종류 오류';end if;
 if jsonb_array_length(q.options)>0 and not q.options ? p_answer then raise exception '선택지를 확인하세요';end if;
 select * into old from mood_records where student_id=s and record_date=d and kind=p_kind and (p_kind='basic' or question_id=p_question_id);
 if old.id is null then v:=case when p_kind='basic' then 1 else least(5,greatest(1,right(q.id,1)::int)) end;
 insert into mood_records(student_id,kind,category,question_id,question,answer,shared,reward) values(s,p_kind,q.category,q.id,q.prompt,trim(p_answer),p_shared,v);
 insert into water_transactions(student_id,amount,reason,reference) values(s,v,'마음 기록',p_kind||':'||d||':'||case when p_kind='basic' then 'daily' else q.id end);
 else update mood_records set answer=trim(p_answer),shared=p_shared,updated_at=now() where id=old.id;end if;
 insert into audit_logs(actor,action,entity) values(s,'record_saved',p_kind);return v;end$$;
create function public.give_water() returns int language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();b bean_inventory;g int;begin select * into b from bean_inventory where student_id=s and completed_at is null for update;if b.id is null then raise exception '콩을 먼저 선택하세요';end if;if balance(s)<1 then raise exception '물방울이 부족해요';end if;g:=b.growth+1;insert into water_transactions(student_id,amount,reason) values(s,-1,'콩에게 물 주기');update bean_inventory set growth=g,completed_at=case when g>=target then now() else null end where id=b.id;if g>=b.target then insert into reward_inventory(student_id,label) values(s,'콩 성장 완료 · 테스트 기프티콘');end if;return g;end$$;
create function public.spin_roulette() returns text language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();r float:=random();v int:=0;label text;begin if balance(s)<3 then raise exception '물방울 3개가 필요해요';end if;insert into water_transactions(student_id,amount,reason) values(s,-3,'룰렛 참여');if r<0.30 then v:=1;label:='물방울 +1';elsif r<0.55 then v:=2;label:='물방울 +2';elsif r<0.70 then v:=3;label:='물방울 +3';elsif r<0.80 then label:='테스트 기프티콘';insert into reward_inventory(student_id,label) values(s,label);elsif r<0.90 then label:='별빛 화분 꾸미기';insert into reward_inventory(student_id,label) values(s,label);else label:='다음 기회에';end if;if v>0 then insert into water_transactions(student_id,amount,reason) values(s,v,'룰렛 당첨');end if;insert into roulette_events(student_id,result) values(s,label);return label;end$$;
create function public.send_request(p_message text,p_id uuid default null,p_cancel boolean default false) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();c uuid;t uuid;begin select classroom_id into c from classroom_members where student_id=s;if c is null then raise exception '먼저 학급에 연결하세요';end if;if p_id is not null then update counseling_requests set message=case when p_cancel then message else p_message end,status=case when p_cancel then '취소' else '확인 전' end,updated_at=now() where id=p_id and student_id=s;if not found then raise exception '요청이 없습니다';end if;else insert into counseling_requests(student_id,classroom_id,message) values(s,c,p_message);end if;select teacher_id into t from classrooms where id=c;insert into notifications(user_id,body) values(t,'학생의 상담 요청이 접수 또는 변경되었습니다.');end$$;
create function public.manage_request(p_id uuid,p_status text,p_followup boolean,p_note text default '') returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from counseling_requests r where r.id=p_id and owns_class(r.classroom_id) and teaches(r.student_id)) then raise exception '접근 권한이 없습니다';end if;update counseling_requests set status=p_status,followup=p_followup,updated_at=now() where id=p_id;if length(trim(p_note))>0 then insert into counseling_notes(request_id,teacher_id,body) values(p_id,auth.uid(),p_note);end if;insert into audit_logs(actor,action,entity) values(auth.uid(),'counseling_updated',p_id::text);end$$;
create function public.use_reward(p_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update reward_inventory set used_at=now() where id=p_id and student_id=auth.uid() and used_at is null;if not found then raise exception '이미 사용했거나 권한이 없습니다';end if;end$$;
create function public.accept_referral(p_inviter uuid) returns void language plpgsql security definer set search_path=public as $$declare s uuid:=require_student();begin if not exists(select 1 from classroom_members where student_id=s) then raise exception '학급 연결 후 초대를 인증할 수 있어요';end if;if not exists(select 1 from profiles where id=p_inviter and role='student') then raise exception '초대자를 확인하세요';end if;if (select created_at from profiles where id=s)<now()-interval '7 days' then raise exception '가입 7일 이내만 가능해요';end if;insert into referrals(invitee,inviter) values(s,p_inviter);insert into water_transactions(student_id,amount,reason,reference) values(p_inviter,1,'친구 초대 성공','invite:'||s);end$$;
create function public.request_deletion() returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception '로그인 필요';end if;insert into deletion_requests(student_id) values(auth.uid()) on conflict do nothing;end$$;
create function public.read_receipt(p_student uuid) returns void language plpgsql security definer set search_path=public as $$begin if not teaches(p_student) then raise exception '접근 권한이 없습니다';end if;insert into audit_logs(actor,action,entity) values(auth.uid(),'student_records_viewed',p_student::text);end$$;
-- Explicit allowlist: internal helpers/trigger functions cannot be called from client.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function my_role(),teaches(uuid),owns_class(uuid),basic_is_shared(uuid) to authenticated;
grant execute on function create_class(text),join_class(text),set_sharing(boolean,boolean),choose_bean(text),save_record(text,text,text,boolean),give_water(),spin_roulette(),send_request(text,uuid,boolean),manage_request(uuid,text,boolean,text),use_reward(uuid),accept_referral(uuid),request_deletion(),read_receipt(uuid) to authenticated;
commit;
